// Normalize Inbound — single channel ADAPTER. CP5d + CRT#3/M2: the LANE is decided by the SIGNATURE HEADER,
// not the body shape. Only a request that PASSED the signature gate carries x-zernio-signature here (a widget
// forging the header without a valid sig was already 403'd at Signature Valid?), so header-present == a
// signature-verified Zernio request. Closes M2: a signed request whose SHAPE drifted is still handled as
// whatsapp (422 + owner-alert), never mistaken for widget (silent 400). The IDOR guard (widget FORCES
// channel='widget') is preserved.
const reject = (lane, reason) => [{ json: { _normalize_reject: true, _reject_lane: lane, _reject_reason: reason } }];
const b = $json.body ?? $json;
const signed = !!(($json.headers || {})['x-zernio-signature']);

if (signed) {                       // signature-verified Zernio -> whatsapp lane; any shape drift -> reject whatsapp
  const m = (b && b.message) || {};
  if (!b || !b.message) return reject('whatsapp', 'signed request but no message object (schema drift)');
  if (m.platform !== 'whatsapp') return reject('whatsapp', `unsupported platform '${m.platform}'`);
  if (m.direction && m.direction !== 'incoming') return reject('whatsapp', 'non-incoming message');
  const senderId = m.sender && m.sender.id;
  if (!senderId) return reject('whatsapp', 'missing sender.id');
  const text = m.text ?? '';
  const message_id = m.platformMessageId || null;
  const conversationId = m.conversationId || null;
  return [{ json: { channel: 'whatsapp', senderId, sender_key: `whatsapp:${senderId}`, text, message_id, conversationId } }];
}

// widget lane (no signature header). FORCE channel='widget'; NEVER trust a payload channel (IDOR).
const senderId = b.sessionId;
if (!senderId) return reject('widget', 'missing sessionId');
const message_id = b.messageId || b.message_id || null;
return [{ json: { channel: 'widget', senderId, sender_key: `widget:${senderId}`, text: b.text, message_id } }];

