={{ (() => {
  const cfg = $('Load Config').first().json.config;
  const t = cfg.messageTemplates;
  const intent = $('Validate Intent').first().json.intent;
  const f = $json.fields;
  const st = $('Merge State').first().json.state; // last_updated_prev = PRE-write snapshot (Merge runs before Save) → previous turn, not this one
  let newSession = true;
  if (st.last_updated_prev) {
    const prev = DateTime.fromISO(st.last_updated_prev, { zone: 'utc' });
    newSession = DateTime.utc().diff(prev, 'minutes').minutes > cfg.bot.sessionGapMinutes;
  }
  const greet = (st.found && newSession) ? 'Welcome back! ' : '';
  // Refactor #5 — computed_reply is the single source of the per-turn reply (every reply-producing builder sets
  // it; both Save States persist it via || ''). ADDITIVE: if present, use it (greet only on collecting). The
  // original resolution below stays a LIVE fallback, reached only when cr is empty (an unforeseen path wrote no
  // reply) — surfaced via the reply_fallback flag.
  const cr = (f.computed_reply || '').trim();
  if (cr) return (f.stage === 'collecting' ? greet : '') + cr;
  try { const ab = $('Build Cancel-Aborted State').first().json; if (ab && ab.computed_reply) return ab.computed_reply; } catch (e) {}
  try { const av = $('Compute Availability').first().json; if (av && av.computed_reply) return av.computed_reply; } catch (e) {}
  if (intent === 'confirm') { for (const n of ['Build Booked State','Build Mirror-Failed State','Build Race-Lost State','Build Orphan State','Build Verify-Unavailable State','Build Cancelled State','Build Cancel-NeedsHuman State']) { try { const r = $(n).first().json; if (r && r.computed_reply) return r.computed_reply; } catch (e) {} } }
  if (intent === 'cancel') { for (const n of ['Build Cancel-Confirm State','Build No-Booking Reply','Build Cancel-Cutoff Reply','Build Cancel-NeedsHuman State']) { try { const r = $(n).first().json; if (r && r.computed_reply) return r.computed_reply; } catch (e) {} } }
  if (intent === 'answer_faq')    return $('Answer FAQ').first().json.computed_reply;
  if (intent === 'capture_lead')  return $('Build Lead State').first().json.computed_reply;
  if (f.stage === 'handoff')      return t.handoff;
  if (f.stage === 'ready')        return greet + 'Great — ' + f.slot_service + ' on ' + f.slot_date + ' at ' + f.slot_time + '. ' + (t.bookingNeedsConfirm || 'Shall I book it?');
  if (f.stage === 'collecting')   return greet + (f.slot_service ? t.askDateTime : t.askService);
  return greet + (t.notUnderstood || 'Sorry — could you rephrase that?');
})() }}

