return [{ json: { ...be, state: { ...st, stage: 'handoff' }, verify_unavailable: true, gcal_event_id: ourId, computed_reply: reply, _post_write: true } }];

// Build Mirror-Failed State — GCal event is written (authoritative) but the Airtable appointments MIRROR failed.
// The booking IS real, so we still confirm to the customer; but flag mirror_failed + keep gcal_event_id so the
// owner (Phase-5 alert) can repair the missing mirror row. Fail-loud on the mirror, never silent.
const cfg = $('Load Config').first().json.config;
const be = $('Build Event Request').first().json;
const b = be.booking;
const st = be.state;
const eventId = $('Build Event Request').first().json.booking.eventId || null;
const t = cfg.messageTemplates;
const reply = (t.bookingConfirmed || `You're booked: {service}, {date} {time}. See you then!`).split('{service}').join(b.serviceName).split('{date}').join(b.dateStr).split('{time}').join(b.timeStr);
return [{ json: { ...be, state: { ...st, stage: 'booked' }, mirror_failed: true, gcal_event_id: eventId, computed_reply: reply, _post_write: true } }];

// Dedupe Gate — Airtable search REPLACES the item, so re-attach the normalized payload from Normalize Inbound.
// Empty search (alwaysOutputData) yields no record id → not a duplicate; a returned record id → already processed.
const norm = $('Normalize Inbound').first().json;
const hit = !!($json && $json.id);
return [{ json: { ...norm, _duplicate: hit } }];

// Outbound tag (Idempotent Replay) — carries this branch's exact response into the shared outbound.
// _outbound_body/_status are the VERBATIM original response (widget stays bit-identical).
return [{ json: { ...$json,
    _outbound_status: 200,
    _outbound_body: (JSON.stringify({ status: 'duplicate_ignored', sender_key: $json.sender_key })),
    _outbound_should_send: false,
    _outbound_kind: "Idempotent Replay"
  } }];

// Outbound tag (Booking State-Unsaved Reply) — carries this branch's exact response into the shared outbound.
// _outbound_body/_status are the VERBATIM original response (widget stays bit-identical).
return [{ json: { ...$json,
    _outbound_status: 200,
    _outbound_body: ((() => { for (const n of ['Build Booked State','Build Mirror-Failed State','Build Race-Lost State','Build Orphan State','Build Verify-Unavailable State','Build Reconcile-Unresolved State']) { try { const r = $(n).first().json; if (r && r.computed_reply) return JSON.stringify({ reply: r.computed_reply, state_unsaved: true, gcal_event_id: r.gcal_event_id || null }); } catch (e) {} } return JSON.stringify({ reply: 'Thanks — a team member will follow up shortly.', state_unsaved: true }); })()),
    _outbound_should_send: true,
    _outbound_kind: "Booking State-Unsaved Reply"
  } }];

// Build Reconcile-Handoff State — the deterministic event id exists but as a CANCELLED tombstone (a prior
// booking for this exact slot was deleted, e.g. a CP2b race-loss). We cannot reuse the id and made no new
// booking → hand off. Context rebuilt via node refs (this is an error/branch path — the incoming item is the
// GCal event, not our state).
const be = $('Build Event Request').first().json;
const st = be.state;
const cfg = $('Load Config').first().json.config;
// computed_reply (Refactor #5): preserve the pre-refactor reply on this path (was generic t.handoff via stage).
return [{ json: { ...be, state: { ...st, stage: 'handoff' }, reconcile_conflict: true, computed_reply: cfg.messageTemplates.handoff } }];

// Verify Reconcile — CP2c-ii: a duplicate-insert 409 (or a reconciled ambiguous failure) is idempotent ONLY if
// the existing event with our deterministic id is LIVE (status != cancelled) AND covers our EXACT slot. A
// race-lost delete leaves the id reserved as a cancelled tombstone → an unverified 409 would falsely report
// "booked". Reconstruct context via node refs; compare times by epoch (Google omits milliseconds).
const be = $('Build Event Request').first().json;
const b = be.booking;
const ev = $json.body;   // Step 1: Get For Reconcile now returns fullResponse -> the event is under .body
const ourStart = new Date(b.startUTC).getTime();
const ourEnd = new Date(b.endUTC).getTime();
const evStart = ev.start && ev.start.dateTime ? new Date(ev.start.dateTime).getTime() : null;
const evEnd = ev.end && ev.end.dateTime ? new Date(ev.end.dateTime).getTime() : null;
const ok = ev.status !== 'cancelled' && evStart === ourStart && evEnd === ourEnd;
return [{ json: { ...be, _reconcile_ok: ok } }];

// Classify Reconcile Failure — STRUCTURAL only (statusCode). Get For Reconcile runs fullResponse+neverError, so
// ANY HTTP response reaches the success output carrying $json.statusCode, and only a transport error reaches the
// error output as $json.error. 200/204 = ok (the event exists → Verify Reconcile checks $json.body against our
// slot); 404/410 = gone (the insert never landed → retry-safe 503); EVERYTHING ELSE = unavailable. FAIL-CLOSED:
// no statusCode / non-number / transport / 401·403 / other 4xx / 5xx all fall to 'unavailable' (a visible handoff)
// — uncertainty NEVER becomes 'ok' or 'gone' (never a false "already there / never created"). No error TEXT is read.
const err = ($json && $json.error) || null;
let cls;
if (err) cls = 'unavailable';
else {
  const sc = Number($json.statusCode);
  if (sc === 200 || sc === 204) cls = 'ok';
  else if (sc === 404 || sc === 410) cls = 'gone';
  else cls = 'unavailable';
}
return [{ json: { ...$json, _reconcile_class: cls } }];

// Build Reconcile-Unresolved State — the reconcile GET was UNRESOLVED (timeout / transport / 5xx); we cannot
// confirm whether the event exists. Do NOT 503 (a retry loops — the deterministic id makes a 2nd insert 409,
// not a double-book, but we still avoid the loop). Hand off with the id visible so the owner can reconcile.
const cfg = $('Load Config').first().json.config;
const be = $('Build Event Request').first().json;
const st = be.state;
const eventId = be.booking.eventId;
const reply = (cfg.messageTemplates.bookingNeedsConfirm) || "Thanks! We're confirming your booking now — a team member will follow up shortly.";
return [{ json: { ...be, state: { ...st, stage: 'handoff' }, reconcile_unresolved: true, gcal_event_id: eventId, computed_reply: reply, _post_write: true } }];

// Cancel Lookup — ASK: pick the sender's OWN next-upcoming booked appt (IDOR-safe: Find Booking filtered by
// sender_key), run the FULL structural validation (Codex#8 LOW-2: never build a confirm prompt on a broken row)
// and decide confirm/none/cutoff/needs_human. EXECUTE ("yes"): bind to the EXACT record confirmed last turn
// (state.cancel_target_id) — NEVER re-pick booked[0]. If that bound row is no longer booked → target_gone (Codex#8
// LOW-3: a NEUTRAL message, never "I found your booking"). The delete-time gate is 'Validate Cancel Target'.
const cfg = $('Load Config').first().json.config;
const vi = $('Validate Intent').first().json;
const st = vi.state;
const now = Date.now();
const cutoffMs = (cfg.bot.cancellationCutoffHours || 0) * 3600 * 1000;
const mode = (vi.intent === 'confirm' && st.stage === 'cancel_confirming') ? 'execute' : 'ask';
const rows = $input.all().map(i => i.json).filter(r => r && r.id && r.fields);
const booked = rows.filter(r => r.fields.status === 'booked' && r.fields.start_utc)
  .sort((a, b) => new Date(a.fields.start_utc) - new Date(b.fields.start_utc));
const mk = (t) => ({ recordId: t.id, gcal_event_id: t.fields.gcal_event_id, calendar_id: t.fields.calendar_id, service: t.fields.service, start_utc: t.fields.start_utc });
const structOk = (t) => {
  const gid = (t.fields.gcal_event_id || '').trim();
  const cal = (t.fields.calendar_id || '').trim();
  return Number.isFinite(new Date(t.fields.start_utc).getTime()) && /^[0-9a-v]{5,1024}$/.test(gid) && cal.length > 0;
};
let outcome, target = null, gone = false;
if (mode === 'execute') {
  const t = booked.find(r => r.id === st.cancel_target_id) || null;
  if (!t) { outcome = 'needs_human'; gone = true; }   // bound row no longer booked → neutral message, never guess
  else { outcome = 'execute'; target = mk(t); }
} else if (booked.length === 0) {
  outcome = 'none';
} else {
  const t = booked[0];
  if (!structOk(t)) outcome = 'needs_human';          // LOW-2: broken row → needs-human BEFORE any confirm prompt
  else if (new Date(t.fields.start_utc).getTime() - now < cutoffMs) outcome = 'cutoff';
  else { outcome = 'confirm'; target = mk(t); }
}
const route = outcome;   // confirm / execute / none / cutoff / needs_human
return [{ json: { ...vi, _cancel_route: route, _cancel_target: target, _cancel_count: booked.length, _cancel_target_gone: gone } }];

// Build Cancel-Confirm State — confirm-before-delete: name the appointment (honesty), note multiple bookings.
// stage=cancel_confirming; persist the confirmed record id (cancel_target_id) so 'yes' binds to THIS exact
// booking, plus confirm_turn = turn_count+1 so the confirm is only honored on the immediate next turn (TTL).
const cfg = $('Load Config').first().json.config;
const j = $json;
const t = j._cancel_target;
const tz = cfg.business.timezone;
const when = DateTime.fromISO(t.start_utc, { zone: 'utc' }).setZone(tz).toFormat('cccc d LLL HH:mm');
const multi = j._cancel_count > 1 ? ` (you have ${j._cancel_count} bookings — this cancels the ${when} one)` : '';
const reply = `Cancel your ${t.service} on ${when}?${multi} Reply "yes" to cancel, or anything else to keep it.`;
return [{ json: { ...j, state: { ...j.state, stage: 'cancel_confirming', cancel_target_id: t.recordId, confirm_turn: String(j.state.turn_count + 1) }, computed_reply: reply } }];

// Build No-Booking Reply — the sender has no active booking to cancel (informational, no state change).
const cfg = $('Load Config').first().json.config;
return [{ json: { ...$json, computed_reply: (cfg.messageTemplates.cancelNoBooking || 'You have no active booking to cancel.') } }];

// Build Cancel-Cutoff Reply — booking is within cancellationCutoffHours of its time → bot won't cancel; hand off.
const cfg = $('Load Config').first().json.config;
return [{ json: { ...$json, state: { ...$json.state, stage: 'handoff' }, computed_reply: (cfg.messageTemplates.cancelCutoff || 'That booking is too close to its time to cancel here — please call us.') } }];

// Build Cancel-NeedsHuman State — cannot safely delete. If the bound target vanished between confirm and "yes"
// (_cancel_target_gone) → a NEUTRAL message (Codex#8 LOW-3: never falsely say "I found your booking"); otherwise
// the row exists but is unsafe to auto-cancel → the found-but-cannot message. Never guess an event id.
const cfg = $('Load Config').first().json.config;
const gone = !!$json._cancel_target_gone;
const reply = gone
  ? (cfg.messageTemplates.cancelTargetGone || "I couldn't find that booking to cancel anymore — a team member will follow up shortly.")
  : (cfg.messageTemplates.cancelNeedsHuman || "I found your booking but can't cancel it automatically — a team member will cancel it for you.");
return [{ json: { ...$json, state: { ...$json.state, stage: 'handoff' }, cancel_needs_human: true, computed_reply: reply } }];

// Classify Cancel Delete — STRUCTURAL only (Codex #8): Delete Booking Event runs fullResponse+neverError, so any
// HTTP response (incl. 4xx/5xx) reaches the success output carrying $json.statusCode, and only a transport error
// (timeout/DNS) reaches the error output as $json.error. 204/200 = deleted; 404/410 = already gone (idempotent);
// anything else (5xx / transport) = UNAVAILABLE — the event may still exist, so NEVER tell the customer 'cancelled'.
// Never inspect the error TEXT: 'host not found' must not be misread as 'booking not found'.
const cl = $('Validate Cancel Target').first().json;
const err = ($json && $json.error) || null;
let outcome;
if (err) outcome = 'unavailable';
else {
  const sc = Number($json.statusCode);
  if (sc === 204 || sc === 200) outcome = 'deleted';
  else if (sc === 404 || sc === 410) outcome = 'gone';
  else outcome = 'unavailable';
}
return [{ json: { ...cl, _cancel_delete: outcome } }];

// Build Cancelled State — GCal event deleted (or already gone) -> booking cancelled. If the Airtable mirror update
// failed, still confirm (GCal is source of truth) but flag it. Reconstruct via node refs.
const cfg = $('Load Config').first().json.config;
const t = $('Validate Cancel Target').first().json._cancel_target;
const del = $('Classify Cancel Delete').first().json._cancel_delete;
const vi = $('Validate Intent').first().json;
const st = vi.state;
const tz = cfg.business.timezone;
const when = DateTime.fromISO(t.start_utc, { zone: 'utc' }).setZone(tz).toFormat('cccc d LLL HH:mm');
const mirrorFail = !!($json && $json.error);
const tmpl = del === 'gone' ? (cfg.messageTemplates.cancelAlreadyDone || 'That booking is already cancelled.') : (cfg.messageTemplates.cancelDone || 'Done — your {service} on {when} is cancelled.');
const reply = tmpl.split('{service}').join(t.service).split('{when}').join(when);
return [{ json: { ...vi, state: { ...st, stage: 'cancelled' }, cancel_mirror_failed: mirrorFail, gcal_event_id: t.gcal_event_id, computed_reply: reply, _post_write: true } }];

// Validate Cancel Target — the structural safety gate BEFORE any delete (Codex #8). Re-validate the bound target:
// start_utc must be a real time (NaN must NOT pass the cutoff check open), still OUTSIDE the cancellation cutoff,
// the gcal_event_id must match the stored id shape, and calendar_id must be present (pre-CP3 rows have none). Any
// failure -> _cancel_valid=false -> never delete -> needs_human. Closes Codex #8: NaN-start, blank/short event id,
// missing calendar_id, and confirm/execute target-binding (the id itself is bound in Cancel Lookup).
const cfg = $('Load Config').first().json.config;
const now = Date.now();
const cutoffMs = (cfg.bot.cancellationCutoffHours || 0) * 3600 * 1000;
const t = $json._cancel_target || {};
const gid = (t.gcal_event_id || '').trim();
const cal = (t.calendar_id || '').trim();
const startMs = new Date(t.start_utc).getTime();
const valid = Number.isFinite(startMs) && (startMs - now >= cutoffMs)
  && /^[0-9a-v]{5,1024}$/.test(gid) && cal.length > 0;
return [{ json: { ...$json, _cancel_valid: valid, _cancel_target: { ...t, gcal_event_id: gid, calendar_id: cal } } }];

// Outbound tag (Cancel Delete Unavailable Reply) — carries this branch's exact response into the shared outbound.
// _outbound_body/_status are the VERBATIM original response (widget stays bit-identical).
return [{ json: { ...$json,
    _outbound_status: 503,
    _outbound_body: ({ ok: false, error: 'calendar_unavailable', cancel_delete_failed: true, reply: $('Load Config').first().json.config.messageTemplates.cancelUnavailable }),
    _outbound_should_send: true,
    _outbound_kind: "Cancel Delete Unavailable Reply"
  } }];

// Build Cancel-Aborted State — the pending cancel confirmation is dropped: either a non-confirm intent arrived
// while awaiting "yes" (Codex#8 fix#2), or the confirmation went stale via an intervening turn (Codex#8 HIGH, TTL
// fail-closed). Clear the confirm state (stage + target + confirm_turn) and tell the customer their booking stands.
const cfg = $('Load Config').first().json.config;
const vi = $('Validate Intent').first().json;
const st = vi.state;
return [{ json: { ...vi, state: { ...st, stage: 'new', cancel_target_id: '', confirm_turn: '' }, computed_reply: (cfg.messageTemplates.cancelAborted || 'No problem — your booking stands.') } }];

// Verify Confirm Live — HIGH mitigation (Codex PART-B re-audit): re-read the conversation IMMEDIATELY before the
// DELETE and re-check the confirmation is still live (stage=cancel_confirming AND confirm_turn unchanged & canonical).
// A concurrent turn that already consumed the confirm changed the stage/turn -> _confirm_live=false -> NO delete.
// NOT atomic (narrows the race from the whole execution to two nodes); the full fix = per-sender serialization /
// atomic compare-and-consume across the whole state model = Phase 5, not a CP3 patch.
const vct = $('Validate Cancel Target').first().json;   // carries _cancel_target for the delete URL
const turnCt = $('Validate Intent').first().json.state.confirm_turn;
const rows = $input.all().map(i => i.json).filter(r => r && r.id && r.fields);
const rer = rows[0] || null;
const live = !!(rer && rer.fields.stage === 'cancel_confirming' && typeof turnCt === 'string' && /^[1-9][0-9]*$/.test(turnCt) && rer.fields.confirm_turn === turnCt);
return [{ json: { ...vct, _confirm_live: live } }];

// Reschedule Lookup — find the sender's OWN next-upcoming booking (the one to MOVE), validate it (cancel-parity:
// finite start_utc · gid shape · calendar_id), enforce the cutoff on the OLD booking, and read the NEW slot from
// this turn's LLM intent (service stays the OLD one, mapped by name). Terminal outcomes set computed_reply inline;
// 'check' carries the new slot (state.slots) + old booking (_reschedule_target) to the availability sub-chain.
const cfg = $('Load Config').first().json.config;
const t = cfg.messageTemplates;
const vi = $('Validate Intent').first().json;
const st = vi.state;
const now = Date.now();
const cutoffMs = (cfg.bot.cancellationCutoffHours || 0) * 3600 * 1000;
const rows = $input.all().map(i => i.json).filter(r => r && r.id && r.fields);
const booked = rows.filter(r => r.fields.status === 'booked' && r.fields.start_utc)
  .sort((a, b) => new Date(a.fields.start_utc) - new Date(b.fields.start_utc));
const structOk = (r) => {
  const gid = (r.fields.gcal_event_id || '').trim();
  const cal = (r.fields.calendar_id || '').trim();
  return Number.isFinite(new Date(r.fields.start_utc).getTime()) && /^[0-9a-v]{5,1024}$/.test(gid) && cal.length > 0;
};
const newDate = (vi.slots && vi.slots.date) || null;
const newTime = (vi.slots && vi.slots.time) || null;
let check = false, computed_reply = '', stage = st.stage, target = null, slots = st.slots || {};
if (booked.length === 0) {
  computed_reply = (t.rescheduleNoBooking || "You don't have a booking to reschedule.");
} else {
  const r = booked[0];
  const svc = (cfg.services || []).find(s => s.name === r.fields.service) || null;
  const mk = () => ({ recordId: r.id, gcal_event_id: r.fields.gcal_event_id, calendar_id: r.fields.calendar_id, service: r.fields.service, serviceId: svc ? svc.id : null, start_utc: r.fields.start_utc });
  if (!structOk(r) || !svc) { stage = 'handoff'; computed_reply = (t.rescheduleNeedsHuman || "I found your booking but can't reschedule it automatically — a team member will help you move it."); }
  else if (new Date(r.fields.start_utc).getTime() - now < cutoffMs) { stage = 'handoff'; computed_reply = (t.rescheduleCutoff || 'That booking is too close to its time to reschedule here — please call us.'); }
  else if (!newDate || !newTime) { target = mk(); computed_reply = (t.rescheduleAskSlot || 'Sure — what new day and time would you like to move it to?'); }
  else { check = true; target = mk(); slots = { serviceId: svc.id, date: newDate, time: newTime }; }
}
return [{ json: { ...vi, state: { ...st, stage, slots }, _resched_check: check, _reschedule_target: target, computed_reply } }];

// Build Reschedule FreeBusy — the NEW slot day's UTC window (shop-tz/DST) for freeBusy (same as booking).
const cfg = $('Load Config').first().json.config;
const tz = cfg.business.timezone;
const date = $json.state.slots.date;
const dayStart = DateTime.fromISO(date, { zone: tz }).startOf('day').toUTC().toISO();
const dayEnd = DateTime.fromISO(date, { zone: tz }).endOf('day').toUTC().toISO();
return [{ json: { ...$json, freebusy: { timeMin: dayStart, timeMax: dayEnd, calId: cfg.googleCalendarId } } }];

// Compute Reschedule Availability — the NEW slot's availability (reuses booking's freeBusy logic; decision A: same
// guards as booking — past/closed rejected, no min-lead-time). available -> reschedule_confirming (confirm lifecycle,
// sub-step 2); busy/past/closed/invalid -> handoff with context. Reads state from Reschedule Lookup + busy from this
// node's freeBusy input.
const cfg = $('Load Config').first().json.config;
const gate = $('Reschedule Lookup').first().json;
const st = gate.state;
const tz = cfg.business.timezone;
const slots = st.slots;
const svc = (cfg.services || []).find(s => s.id === slots.serviceId);
const dur = svc.durationMin;
const svcName = svc.name;
const start = DateTime.fromISO(slots.date + 'T' + slots.time, { zone: tz });
const end = start.plus({ minutes: dur });
const now = DateTime.now().setZone(tz);
const wdKey = ['mon','tue','wed','thu','fri','sat','sun'][start.weekday - 1];
const windows = (cfg.workingHours && cfg.workingHours[wdKey]) || [];
const wins = windows.map(w => { const p = w.split('-'); return { open: DateTime.fromISO(slots.date + 'T' + p[0], { zone: tz }), close: DateTime.fromISO(slots.date + 'T' + p[1], { zone: tz }) }; });
const cals = $json.calendars || {};
const firstCal = Object.values(cals)[0] || { busy: [] };
if (firstCal.errors && firstCal.errors.length) throw new Error('calendar_error: ' + JSON.stringify(firstCal.errors));
const busy = (firstCal.busy || []).map(b => ({ s: DateTime.fromISO(b.start), e: DateTime.fromISO(b.end) }));
const overlaps = (s, e) => busy.some(b => s < b.e && b.s < e);
const withinHours = (s, e) => wins.some(w => s >= w.open && e <= w.close);
const fmt = start.toFormat('cccc d LLL HH:mm');
let status, reply, stage = 'handoff', extra = {};
if (!slots.date || !slots.time || !start.isValid) { status = 'invalid'; reply = "I couldn't read that new time — a team member will help you pick one."; }
else if (start < now) { status = 'past'; reply = `${fmt} has already passed — a team member will help you pick a new time.`; }
else if (wins.length === 0 || !withinHours(start, end)) { status = 'closed'; reply = `We're closed then — a team member will help you pick a time that works.`; }
else if (overlaps(start, end)) { status = 'busy'; reply = `${fmt} is taken — a team member will help you find another time.`; }
else {
  status = 'available';
  const oldWhen = DateTime.fromISO(gate._reschedule_target.start_utc, { zone: 'utc' }).setZone(tz).toFormat('cccc d LLL HH:mm');
  reply = `Move your ${gate._reschedule_target.service} from ${oldWhen} to ${fmt}? Reply \"yes\" to move it, or anything else to keep it.`;
  stage = 'reschedule_confirming';
  extra = { cancel_target_id: gate._reschedule_target.recordId, confirm_turn: String(st.turn_count + 1) };
}
return [{ json: { ...gate, state: { ...st, stage, ...extra }, resched_availability: status, computed_reply: reply } }];

// Build Reschedule-Aborted State — the pending reschedule confirmation is dropped (a non-confirm intent arrived, or
// the confirmation went stale via an intervening turn / TTL). Clear the confirm state; the booking stays at its
// ORIGINAL time. Fail-closed twin of Build Cancel-Aborted State.
const cfg = $('Load Config').first().json.config;
const vi = $('Validate Intent').first().json;
const st = vi.state;
return [{ json: { ...vi, state: { ...st, stage: 'new', cancel_target_id: '', confirm_turn: '' }, computed_reply: (cfg.messageTemplates.rescheduleAborted || 'No problem — your booking stays as it is.') } }];

// Validate Reschedule Target — on the reschedule confirm ("yes") turn, bind to the EXACT OLD
// appointment the customer confirmed (state.cancel_target_id, set by Compute Reschedule Availability)
// among the sender's OWN booked rows (IDOR-safe: Find Old Booking filters by sender_key). Re-validate
// that OLD row structurally (finite start_utc, gcal_event_id shape, calendar_id present) AND still
// OUTSIDE the cancellation cutoff. Any failure -> _reschedule_valid=false -> NeedsHuman (NO delete, NO
// insert). Fused twin of Cancel Lookup(execute) + Validate Cancel Target — reschedule re-finds and
// re-validates the OLD booking in one step. gid regex is the shared cancel-validation shape.
const cfg = $('Load Config').first().json.config;
const vi = $('Validate Intent').first().json;
const st = vi.state;
const now = Date.now();
const cutoffMs = (cfg.bot.cancellationCutoffHours || 0) * 3600 * 1000;
const rows = $input.all().map(i => i.json).filter(r => r && r.id && r.fields);
const booked = rows.filter(r => r.fields.status === 'booked' && r.fields.start_utc);
const t = booked.find(r => r.id === st.cancel_target_id) || null;
let valid = false, target = null;
if (t) {
  const gid = (t.fields.gcal_event_id || '').trim();
  const cal = (t.fields.calendar_id || '').trim();
  const startMs = new Date(t.fields.start_utc).getTime();
  valid = Number.isFinite(startMs) && (startMs - now >= cutoffMs)
    && /^[0-9a-v]{5,1024}$/.test(gid) && cal.length > 0;
  target = { recordId: t.id, gcal_event_id: gid, calendar_id: cal, service: t.fields.service, start_utc: t.fields.start_utc };
}
return [{ json: { ...vi, _reschedule_valid: valid, _reschedule_target: target } }];

// Build Reschedule Event Request — clone of Build Event Request for the NEW slot (state.slots is the new
// slot, persisted by Compute Reschedule Availability). ONLY change: spread ...$json (NOT ...vi) so the
// _reschedule_target added by Validate Reschedule Target survives for (c) update/delete. GCal events.insert from confirmed slots (shop tz + UTC, DST-correct, NO attendees).
const cfg = $('Load Config').first().json.config;
const vi = $('Validate Intent').first().json;
const st = vi.state;
const slots = st.slots;
const tz = cfg.business.timezone;
const svc = (cfg.services || []).find(s => s.id === slots.serviceId);
if (!svc) throw new Error('Build Event Request: serviceId "' + slots.serviceId + '" not in config.services — Slot Gate/Merge Slots must block invalid services (no silent 30-min fallback)'); // fail-loud, not a silent wrong booking
const dur = svc.durationMin;
const svcName = svc.name;
const name = (vi.slots && vi.slots.customerName) || null;
const start = DateTime.fromISO(slots.date + 'T' + slots.time, { zone: tz });
const end = start.plus({ minutes: dur });
const summary = svcName + (name ? ' — ' + name : '') + ' (bot)';
// CP2c-ii: deterministic GCal event id from the BOOKING KEY (sender_key|date|time|service), hex-encoded
// (valid base32hex, injective → no collisions). Same booking key → same id → a duplicate insert 409s, so a
// retry (or an insert whose response was lost) reconciles to the existing event instead of double-booking.
const bkey = [vi.sender_key, slots.date, slots.time, slots.serviceId].join('|');
if (!/^[\x00-\x7F]+$/.test(bkey)) throw new Error('Build Event Request: booking key has non-ASCII — the allow-list/senderId guard should keep it ASCII'); // Codex defense-in-depth
// UTF-8 byte encoding (NOT charCodeAt — that truncates surrogate pairs, so 😀 and 😁 would collide to the
// same id, letting a crafted sessionId reconcile onto another customer's event). TextEncoder is a global (no require).
const eventId = Array.from(new TextEncoder().encode(bkey)).map(b => b.toString(16).padStart(2, '0')).join('');
return [{ json: { ...$json, booking: { calId: cfg.googleCalendarId, timeZone: tz, startISO: start.toISO(), endISO: end.toISO(), startUTC: start.toUTC().toISO(), endUTC: end.toUTC().toISO(), summary, service: slots.serviceId, serviceName: svcName, customerName: name, dateStr: start.toFormat('cccc d LLL'), timeStr: start.toFormat('HH:mm'), eventId } } }];

// Build Reschedule Insert-Failed State — the GCal insert for the NEW time failed (error, or a 409
// lost-response retry). We deliberately do NOT reconcile: message-level idempotency (processed_messages)
// already dedupes a repeated messageId, so the only 409 is a rare lost-response — and the customer's
// ORIGINAL booking is still intact (book-new-first order: nothing was deleted). Tell them the original
// stands; hand off. Reads Validate Intent because the error item carries no input fields. Post-write ->
// Save State (Post-Write).
const cfg = $('Load Config').first().json.config;
const vi = $('Validate Intent').first().json;
const st = vi.state;
return [{ json: { ...vi, state: { ...st, stage: 'handoff', cancel_target_id: '', confirm_turn: '' }, computed_reply: (cfg.messageTemplates.rescheduleInsertFailed || "Sorry — I couldn't move your booking; your original appointment still stands. A team member will follow up.") } }];

// Build Reschedule-NeedsHuman State — the OLD booking to move could not be re-validated on the confirm
// turn (target vanished, structurally broken row, or now inside the cancellation cutoff). NO GCal insert
// and NO delete happened on this branch — the customer's ORIGINAL booking stands untouched. Hand off.
// Pre-write -> Save State (like a low-confidence handoff).
const cfg = $('Load Config').first().json.config;
const vi = $('Validate Intent').first().json;
const st = vi.state;
return [{ json: { ...vi, state: { ...st, stage: 'handoff' }, computed_reply: (cfg.messageTemplates.rescheduleNeedsHuman || 'I found your booking but can\'t reschedule it automatically — a team member will help you move it.') } }];

// Check Race — write-then-verify (booking-integrity): after our GCal insert, re-read the slot window.
// Any OTHER event overlapping our slot means we lost the concurrency race and must yield OUR event.
// events.list returns the RAW list (unlike freeBusy) — exclude cancelled + transparent ("Free") events.
const cfg = $('Load Config').first().json.config;
const tz = cfg.business.timezone;
const be = $('Build Reschedule Event Request').first().json;
const b = be.booking;
const ourId = $('Build Reschedule Event Request').first().json.booking.eventId;
const ourStart = new Date(b.startUTC).getTime();
const ourEnd = new Date(b.endUTC).getTime();
// Codex #3+#4: the verify read is INCOMPLETE if it was paginated (nextPageToken) OR the calendar's own
// timezone differs from the shop tz (all-day boundary math would be wrong). Fail safe: yield our event +
// mark verify_incomplete so the customer gets a NEUTRAL "couldn't confirm" message (never "just taken"),
// and never enter the happy path on an uncertain read.
const calTz = $json.timeZone;
if ($json.nextPageToken || (calTz && calTz !== tz)) {
  return [{ json: { ...be, gcal_event_id: ourId, race_lost: true, race_other_count: -1, verify_incomplete: true } }];
}
// Codex #5: all-day events carry start.date (no time) — parse at shop-tz midnight, NOT UTC midnight.
const toMs = (p) => {
  if (!p) return null;
  if (p.dateTime) return new Date(p.dateTime).getTime();
  if (p.date) return DateTime.fromISO(p.date, { zone: tz }).toMillis();
  return null;
};
const items = $json.items || [];
const overlaps = items.filter(ev => {
  if (ev.status === 'cancelled') return false;
  if (ev.transparency === 'transparent') return false;
  const s = toMs(ev.start);
  const e = toMs(ev.end);
  if (s === null || e === null) return false;
  return s < ourEnd && e > ourStart;
});
const others = overlaps.filter(ev => ev.id !== ourId);
return [{ json: { ...be, gcal_event_id: ourId, race_lost: others.length >= 1, race_other_count: others.length } }];

// Build Race-Lost State — lost the race AND successfully deleted OUR event (clean withdrawal).
// Slot yielded to the other booking; customer handed to a human. No orphan (our event is gone).
const cfg = $('Load Config').first().json.config;
const be = $('Build Reschedule Event Request').first().json;
const st = be.state;
const vi = (() => { try { return $('Check Race (Reschedule)').first().json.verify_incomplete === true; } catch (e) { return false; } })();
const reply = vi ? (cfg.messageTemplates.verifyIncomplete || 'We could not finish confirming that time just now — a team member will follow up to lock it in.') : ((cfg.messageTemplates.slotJustTaken) || 'Sorry — that time was just taken. A team member will help you find another slot.');
return [{ json: { ...be, state: { ...st, stage: 'handoff' }, race_lost: true, gcal_event_id: null, computed_reply: reply, _post_write: true } }];

// Build Reschedule Verify-Unavailable State — the post-write verify READ failed on the NEW event (calendar
// unreachable). The NEW event IS written and the OLD booking is untouched. Do NOT delete (could cancel a legit
// event) and do NOT 503 (retry would double-book). Keep the new event, OLD stands, hand off, flag for the owner.
// The event IS written. We do NOT delete on a read-failure (could cancel a legit sole booking) and we do
// NOT return 503 (a provider retry would double-book). Keep the event, hand off, flag distinctly for the owner.
const cfg = $('Load Config').first().json.config;
const be = $('Build Reschedule Event Request').first().json;
const st = be.state;
const ourId = $('Build Reschedule Event Request').first().json.booking.eventId;
const reply = (cfg.messageTemplates.verifyIncomplete) || 'We could not finish confirming that time just now — a team member will follow up to lock it in.';
return [{ json: { ...be, state: { ...st, stage: 'handoff' }, verify_unavailable: true, gcal_event_id: ourId, computed_reply: reply, _post_write: true } }];

// Build Orphan State — lost the race but the DELETE of our event FAILED → our event is still on the calendar.
// Visible, recoverable double-book: persist gcal_event_id so the owner can delete the stray event by hand.
const cfg = $('Load Config').first().json.config;
const be = $('Build Reschedule Event Request').first().json;
const st = be.state;
const ourId = $('Build Reschedule Event Request').first().json.booking.eventId;
const vi = (() => { try { return $('Check Race (Reschedule)').first().json.verify_incomplete === true; } catch (e) { return false; } })();
const reply = vi ? (cfg.messageTemplates.verifyIncomplete || 'We could not finish confirming that time just now — a team member will follow up to lock it in.') : ((cfg.messageTemplates.slotJustTaken) || 'Sorry — that time was just taken. A team member will help you find another slot.');
return [{ json: { ...be, state: { ...st, stage: 'handoff' }, orphan_event: true, gcal_event_id: ourId, computed_reply: reply, _post_write: true } }];

// Classify Reschedule Delete — STRUCTURAL only (statusCode). Delete Old Event runs fullResponse+neverError,
// so any HTTP status reaches success output as $json.statusCode; only a transport error (timeout/DNS) reaches
// error output as $json.error. 204/200 = done (old removed); 404/410 = gone (old already absent — still a
// successful move); anything else = unavailable (the OLD event may still linger). NEVER inspect error text.
const base = $('Build Reschedule Event Request').first().json;
const err = ($json && $json.error) || null;
let outcome;
if (err) outcome = 'unavailable';
else {
  const sc = Number($json.statusCode);
  if (sc === 204 || sc === 200) outcome = 'done';
  else if (sc === 404 || sc === 410) outcome = 'gone';
  else outcome = 'unavailable';
}
return [{ json: { ...base, _reschedule_delete: outcome } }];

// Build Reschedule-Done State — the move is committed: row points at the NEW event and the OLD event was
// deleted (204/200) or was already gone (404/410 — still a success). stage=booked, carry the NEW gcal id,
// clear the confirm state. "Moved — your {service} is now {when}."
const cfg = $('Load Config').first().json.config;
const be = $('Build Reschedule Event Request').first().json;
const b = be.booking;
const vi = $('Validate Intent').first().json;
const st = vi.state;
const eventId = b.eventId || null;
const when = b.dateStr + ' ' + b.timeStr;
const reply = (cfg.messageTemplates.rescheduleDone || 'Moved — your {service} is now {when}.').split('{service}').join(b.serviceName).split('{when}').join(when);
return [{ json: { ...vi, state: { ...st, stage: 'booked', cancel_target_id: '', confirm_turn: '' }, gcal_event_id: eventId, computed_reply: reply, _post_write: true } }];

// Build Reschedule Orphan State — the row is updated to the NEW event and the NEW event exists, so the move
// succeeded for the customer; but deleting the OLD event was UNAVAILABLE, so it lingers on the calendar.
// Tell the customer the truth — it moved — and hand off with reschedule_orphan so the owner removes the stray
// OLD event (visible, recoverable — never silent).
const cfg = $('Load Config').first().json.config;
const be = $('Build Reschedule Event Request').first().json;
const b = be.booking;
const vi = $('Validate Intent').first().json;
const st = vi.state;
const eventId = b.eventId || null;
const when = b.dateStr + ' ' + b.timeStr;
const reply = (cfg.messageTemplates.rescheduleDone || 'Moved — your {service} is now {when}.').split('{service}').join(b.serviceName).split('{when}').join(when);
return [{ json: { ...vi, state: { ...st, stage: 'handoff', cancel_target_id: '', confirm_turn: '' }, reschedule_orphan: true, gcal_event_id: eventId, computed_reply: reply, _post_write: true } }];

// Build Reschedule Mirror-Failed State — the NEW event is booked+verified, but the Airtable appointments row
// UPDATE failed, so the row still points at the OLD event (stale) while both events exist. The DB is
// inconsistent, so we do NOT claim a clean move; hand off with reschedule_mirror_failed + the NEW gcal id so a
// human reconciles. Reads Build Reschedule Event Request + Validate Intent (the error item carries no fields).
const cfg = $('Load Config').first().json.config;
const be = $('Build Reschedule Event Request').first().json;
const vi = $('Validate Intent').first().json;
const st = vi.state;
const eventId = be.booking.eventId || null;
const reply = cfg.messageTemplates.rescheduleMirrorFailed || 'Your booking change is being finalized — a team member will confirm the new time shortly.';
return [{ json: { ...vi, state: { ...st, stage: 'handoff' }, reschedule_mirror_failed: true, gcal_event_id: eventId, computed_reply: reply, _post_write: true } }];

// Finalize Outbound — single outbound decision point.
const nz = $('Normalize Inbound').first().json;
let body = $json._outbound_body;
// a few branches carry a STRING (JSON.stringify) body — parse it so the whatsapp reply
// text (CP4b-2) can be read from it; widget is unaffected (it emits _outbound_body verbatim).
let parsed = body;
if (typeof parsed === 'string') { try { parsed = JSON.parse(parsed); } catch (e) { parsed = {}; } }
const reply = ($json._outbound_reply ?? ((parsed && parsed.reply) || '')) + '';
return [{ json: { ...$json, channel: nz.channel, conversationId: nz.conversationId || null, _outbound_reply: reply } }];

// Outbound Send Failed — the Zernio send errored. VISIBLE (owner-alert = Phase 5).
// The webhook already ACKed 200 (before the send), so NO 5xx here -> no provider retry storm.
return [{ json: { ...$json, error: 'zernio_send_failed', _outbound_owner_flag: true } }];

// Owner-alert composer + THROTTLE + class derivation (CP5a) — single general mechanism.
// ALL alert sources fan in here. OFF the reply path: returns [] to suppress (disabled / throttled /
// kill-switch guard-trip / not alert-worthy). A failure here never touches the customer reply.
const lc = $('Load Config').first().json;
const cfg = (lc && lc.config) ? lc.config : {};
const oa = cfg.ownerAlert || {};
if (oa.enabled !== true) return [];
const j = $json || {};
const st = j.state || {};
const KIND = {
  'Handoff Lock Reply': 'handoff_lock',
  'Send Error Response': 'state_unavailable',
  'LLM Unavailable Reply': 'llm_unavailable',
  'Lead Unavailable Reply': 'lead_unavailable',
  'Calendar Unavailable Reply': 'calendar_unavailable',
  'Booking State-Unsaved Reply': 'state_unsaved',
  'Cancel Delete Unavailable Reply': 'cancel_delete_failed',
};
let cls = null;
const kind = j._outbound_kind;
if (kind === 'Handoff Reply') {
  if (cfg.bot && cfg.bot.killSwitch === true) return [];   // KK2: kill-switch trip is owner-initiated -> no ping
  cls = 'max_turns';                                        // KK2: max-turns trip -> ping
} else if (kind && KIND[kind]) { cls = KIND[kind]; }
else if (j.spend_cap_tripped) { cls = 'spend_cap'; }
else if (j.spend_meter_unavailable) { cls = 'spend_meter_unavailable'; }
else if (j.normalize_drift) { cls = 'normalize_drift'; }
else if (j.dedupe_marker_failed) { cls = 'dedupe_marker_failed'; }
else if (j.error) { cls = j.error; }                        // zernio_send_failed + any error-tagged node
else if (j.orphan_event || j.reschedule_orphan) cls = 'orphan_event';
else if (j.mirror_failed || j.reschedule_mirror_failed) cls = 'mirror_failed';
else if (j.verify_unavailable) cls = 'verify_unavailable';
else if (j.reconcile_unresolved) cls = 'reconcile_unresolved';
else if (j.reconcile_conflict) cls = 'reconcile_conflict';
else if (j.state_unsaved) cls = 'state_unsaved';
else if (j.cancel_delete_failed) cls = 'cancel_delete_failed';
else if (j.cancel_needs_human) cls = 'cancel_needs_human';
else if (j.reply_fallback === true) cls = 'reply_fallback';
else if (st.stage === 'handoff') cls = 'handoff';
if (!cls) return [];                                        // not alert-worthy -> no alert
const pick = (...xs) => xs.find(v => v !== undefined && v !== null && v !== '') || 'unknown';
const sender  = pick(st.sender_key, j.sender_key);
const channel = pick(st.channel, j.channel);
const intent  = pick(st.last_intent, j.last_intent, j.intent);
const stage   = pick(st.stage, j.stage);
const windowMin = Number(oa.throttleMinutes) > 0 ? Number(oa.throttleMinutes) : 30;
const key = cls + ':' + sender;
const now = Date.now();
const sd = $getWorkflowStaticData('global');
sd.ownerAlerts = sd.ownerAlerts || {};
const last = sd.ownerAlerts[key];
if (typeof last === 'number' && (now - last) < windowMin * 60 * 1000) return [];  // throttled
sd.ownerAlerts[key] = now;
const slots = st.slots || j.slots || {};
const slotStr = [slots.service || slots.serviceId, slots.date, slots.time].filter(Boolean).join(' / ');
const lines = ['\ud83d\udd14 Salon bot \u2014 ' + cls, 'sender: ' + sender, 'channel: ' + channel, 'intent: ' + intent, 'stage: ' + stage];
if (slotStr) lines.push('slots: ' + slotStr);
const recent = (st.recent_messages || '').split(String.fromCharCode(10)).filter(Boolean).slice(-5);
if (recent.length) lines.push('recent: ' + recent.join(' | '));
if (j.normalize_reason) lines.push('reason: ' + j.normalize_reason);
const text = lines.join('\n').replace(/[_*`\[\]~]/g, '-');  // Telegram Markdown-safe (class names carry '_')
return [{ json: { owner_alert_text: text, _alert_class: cls } }];

// Owner-alert delivery FAILED (Telegram unreachable). Visible marker only; the customer reply is on a
// separate branch and is unaffected (CP5a D-c invariant).
return [{ json: { owner_alert_failed: true, error: ($json.error && $json.error.message) || 'telegram_send_failed' } }];

// Turnstile passed — restore the normalized message ($json was the siteverify response) so
// Validate Payload downstream reads the customer message again, not the CF verdict.
return [{ json: $('Normalize Inbound').first().json }];

// Eval Spend — read the period's accumulated LLM cost + restore the message item.
// Read Spend (Airtable) clobbers $json → restore the brain input from Merge State (single-output, always run).
// Fail-OPEN (K-SPEND): missing row OR a read error → prev spend = 0 (the LLM still runs); the alert leaf warns the owner.
const ctx = $('Merge State').first().json;            // {channel, senderId, sender_key, text, state}
const cfg = $('Load Config').first().json.config;
const capNum = Number(cfg.bot.llmCostCapUsd);
const cap = Number.isFinite(capNum) ? capNum : null;  // null = no cap configured -> never blocks (no Infinity in JSON)
const rec = $json || {};
const fields = rec.fields || rec;                     // Airtable search item = {id, fields:{cost_usd,...}}
const prevRaw = Number(fields.cost_usd);
const prev = Number.isFinite(prevRaw) ? prevRaw : 0;
const under = cap === null ? true : prev < cap;
return [{ json: { ...ctx, _spend: { prev, cap, under } } }];

// Spend-cap trip — the monthly LLM budget is reached. Deterministic handoff reply (no LLM), owner alerted.
// Transient guard-trip: 200, NO state write (mirrors Handoff Reply / max-turns). OFF the reply path it also fans to the owner-alert.
return [{ json: { ...$json,
    _outbound_status: 200,
    _outbound_body: ({ ok: true, handoff: true, reply: $('Load Config').first().json.config.messageTemplates.handoff }),
    _outbound_should_send: true,
    _outbound_kind: "Spend-Cap Reply",
    spend_cap_tripped: true
  } }];

// Spend-meter unavailable — the bot_metrics read OR write failed (Airtable). Fail-OPEN: the LLM still runs,
// but the owner MUST know the spend brake is blind (visible failure). Pure alert leaf — never on the reply path.
const ctx = $('Merge State').first().json;   // best-effort sender context (present in both the read-fail and write-fail cases)
const st = (ctx && ctx.state) || {};
return [{ json: {
    spend_meter_unavailable: true,
    sender_key: ctx && ctx.sender_key,
    channel: ctx && ctx.channel,
    state: st
  } }];

// Build Spend Record — estimate this call's cost and add it to the period's running total.
// prev = the spend read at guard time THIS execution (Eval Spend); delta = tokens x config price (Haiku 4.5).
// TOCTOU across concurrent turns is accepted at this tier (a soft brake, not an atomic ledger).
const cfg = $('Load Config').first().json.config;
const usage = $json.usage || {};                       // Anthropic Messages API response usage (top-level)
const inTok = Number(usage.input_tokens) || 0;
const outTok = Number(usage.output_tokens) || 0;
const priceIn = Number(cfg.bot.llmPricePer1kTokensIn) || 0;
const priceOut = Number(cfg.bot.llmPricePer1kTokensOut) || 0;
const delta = (inTok / 1000) * priceIn + (outTok / 1000) * priceOut;
const prev = Number($('Eval Spend').first().json._spend.prev) || 0;
const period = $now.toUTC().toFormat('yyyy-MM');       // UTC month bucket (matches Read Spend)
return [{ json: {
    period_key: period,
    cost_usd: Number((prev + delta).toFixed(6)),
    updated_at: $now.toUTC().toISO(),
    _delta: Number(delta.toFixed(6))
  } }];

// Dry-run booking — global bot.dryRun is ON. NO real GCal event is created; persist a booked-looking
// state (dry_run flagged, empty gcal_event_id) so the flow is testable end-to-end without a real write.
// A later cancel/reschedule finds no appointments row (Write Appointment was skipped) -> safe no-op.
const cfg = $('Load Config').first().json.config;
const be = $('Build Event Request').first().json;
const b = be.booking;
const st = be.state;
const t = cfg.messageTemplates;
const reply = (t.bookingConfirmed || "You're booked: {service}, {date} {time}. See you then!")
  .split('{service}').join(b.serviceName).split('{date}').join(b.dateStr).split('{time}').join(b.timeStr);
return [{ json: { ...be, state: { ...st, stage: 'booked' }, gcal_event_id: '', computed_reply: reply, dry_run: true, _post_write: true } }];

// Verify Signature (CP5d + CRT#3/L1) — constant-time compare + strict input validation.
// crypto.timingSafeEqual is unavailable here (spike-verified) -> plain-JS. BOTH the computed HMAC and the header
// signature must be a STRING of EXACTLY 64 lowercase-hex chars; the type/length validity is folded into the
// diff (closes coercion cases: an array/number/wrong-length header). Always scan 64 positions.
// Comparison HYGIENE / clean audit, NOT a claimed defense against a real timing attack.
const raw = ($json.headers || {})['x-zernio-signature'];
const a = (typeof $json.computedSig === 'string') ? $json.computedSig : '';
const b = (typeof raw === 'string') ? raw : '';
const HEX64 = /^[0-9a-f]{64}$/;
let diff = (HEX64.test(a) && HEX64.test(b)) ? 0 : 1;
for (let i = 0; i < 64; i++) diff |= ((a.charCodeAt(i) | 0) ^ (b.charCodeAt(i) | 0));
return [{ json: { ...$json, sig_valid: diff === 0 } }];

// Build Normalize Reject (CP5d) — front-gate reject for an unrecognized inbound shape. Responds DIRECTLY
// (not via the conversational outbound) like Reject Unsigned Request. whatsapp lane = authentic Zernio drift
// (already signature-verified) -> 422 + owner-alert; widget lane -> 400, NO alert. The widget endpoint is
// UNAUTHENTICATED: letting it trigger an owner-alert would be a DoS primitive against the owner's Telegram.
// 422 (not 5xx) also leaves an independent failure signal in Zernio's OWN logs, separate from our alert channel.
const j = $json;
const wa = j._reject_lane === 'whatsapp';
return [{ json: { ...j,
  _reject_status: wa ? 422 : 400,
  _reject_body: wa ? { ok: false, error: 'normalize_failed' } : { ok: false, error: 'bad_request' },
  normalize_drift: wa ? true : undefined,
  normalize_reason: j._reject_reason,
  channel: wa ? 'whatsapp' : 'widget'
} }];

// Build Dedupe-Marker Alert (CRT#3/M1a) — `Record Processed` (the idempotency-marker write) FAILED. The
// customer response already went out; this is a pure side-effect alert so the owner learns the dedupe store is
// failing (a later duplicate could then double-process). OFF the reply path. Context from Merge State (ran in
// both the normal and post-write branches).
const ctx = $('Merge State').first().json;
return [{ json: { dedupe_marker_failed: true, sender_key: ctx && ctx.sender_key, channel: ctx && ctx.channel, state: (ctx && ctx.state) || {} } }];
